# Description: A multimodal optimization benchmark with sinusoidal perturbations added to a quadratic basin, creating multiple local minima while maintaining clear global optima.
# Code:
```python
import numpy as np

class MultimodalGridBenchmark:
    def __init__(self, dim):
        self.dim = dim

    def f(self, x):
        if len(x) != self.dim:
            raise ValueError("Dimension mismatch")

        # Quadratic basin term - encourages convergence to center
        basin_term = 0.1 * np.sum(x**2)

        # Multimodal terms with sinusoidal perturbations
        multimodal_term = 0.0
        for i in range(-2, 3):
            for j in range(-2, 3):
                if i == 0 and j == 0:
                    continue  # Skip the center point
                # Use first two dimensions for the grid pattern
                if self.dim >= 2:
                    distance = (x[0] - 2*i)**2 + (x[1] - 2*j)**2
                    multimodal_term += 1.0 / (1.0 + distance)

        # Add center minimum
        if self.dim >= 2:
            distance_center = x[0]**2 + x[1]**2
            multimodal_term += 5.0 / (1.0 + distance_center)

        # Sinusoidal perturbations to increase complexity
        sin_perturbation = np.sum(np.sin(x * 0.5))

        return basin_term - multimodal_term + sin_perturbation
```

# Description: A chaotic optimization landscape combining sinusoidal waves with polynomial penalties to create a non-convex, highly multimodal function with irregular valleys and ridges.
# Code:
```python
import numpy as np

class ChaoticMultimodalBenchmark:
    def __init__(self, dim):
        self.dim = dim

    def f(self, x):
        if len(x) != self.dim:
            raise ValueError("Dimension mismatch")

        # Sinusoidal base with varying frequencies
        sin_term = 0.0
        for i in range(self.dim):
            sin_term += np.sin(2 * np.pi * x[i]) * np.sin(3 * np.pi * x[i])

        # Polynomial penalty for staying away from boundaries
        penalty = 0.0
        for i in range(self.dim):
            penalty += (abs(x[i]) - 5.0)**4

        # Chaotic component using logistic map-like behavior
        chaotic = 0.0
        for i in range(self.dim):
            chaotic += np.sin(np.pi * x[i] * np.cos(x[i]))

        # Add interaction terms between dimensions
        interaction = 0.0
        for i in range(self.dim):
            for j in range(i+1, self.dim):
                interaction += (x[i] - x[j])**2 * np.sin(x[i] + x[j])

        return sin_term + penalty + chaotic + interaction
```

# Description: A chaotic optimization benchmark function combining sinusoidal oscillations with polynomial potentials to create a landscape with numerous local minima and saddle points, challenging optimization algorithms with irregular terrain.
# Code:
